mapper.select:
SELECT

FROM WalletAssetFlows a WHERE 1 = 1

    AND a.accountId = #{accountId}


    AND a.currency LIKE CONCAT('%',#{currency}, '%') 


    AND a.businessCategory LIKE CONCAT('%',#{businessCategory}, '%')


    AND a.businessType LIKE CONCAT('%',#{businessType}, '%') 


    AND a.beforeBalance = #{beforeBalance}


    AND a.balance = #{balance}


    AND a.direction = #{direction}


    AND a.afterBalance = #{afterBalance}


    AND a.orgBusinessId = #{orgBusinessId}


    AND a.orgBusinessNo = #{orgBusinessNo}


    AND a.status = #{status}


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}


    AND a.remark LIKE CONCAT('%',#{remark}, '%') 

order by a.createTime desc
